const topics = [
  {name:'Цепочка решения',tag:'ОСНОВА РАЗБОРА',question:'Ты умер после ротации. Как найти первое решение, которое можно было изменить?',answer:'Начни не с момента смерти. Выпиши по порядку: какая информация была до выхода, когда выбрал маршрут, что изменилось по пути и какое действие последовало. Первое звено, где была доступная альтернатива, — кандидат для практики. Реплей может показать больше, чем ты знал в игре; не подменяй одно другим.',drill:'После матча запиши три стрелки: информация → решение → последствие. Отметь, где факт, а где гипотеза.'},
  {name:'Первый размен',tag:'ФАЙТЫ',question:'Ты нанёс урон, но файт всё равно проигран. Достаточно ли этого, чтобы считать пик хорошим?',answer:'Нет. Урон — только часть решения. Проверь укрытие после выстрела, путь отхода, HP, угол тиммейта и возможность соперника ответить. Даже выигранный размен может быть плохим, если оставил тебя без безопасного продолжения.',drill:'В двух файтах перед пиком назови укрытие и путь назад. После — отметь, сохранились ли они.'},
  {name:'Ротация до таймера',tag:'МАКРО',question:'Когда лучше выбрать маршрут: до начала движения или после появления угрозы?',answer:'Маршрут и условие его смены полезно выбрать заранее по известной зоне, времени, ресурсам и видимым угрозам. Во время движения можно менять план, но тогда ты понимаешь, что именно изменилось, вместо хаотичной реакции.',drill:'Перед двумя ротациями запиши основной путь и один триггер смены. После матча сравни план с действием.'},
  {name:'Командный колл',tag:'КОМАНДА',question:'Ты сказал «го», а тиммейт не пошёл. Кто ошибся?',answer:'Одной фразы мало для вывода. Восстанови, какую цель, момент входа и подтверждение получил каждый игрок. Иногда проблема в опоздавшей информации, иногда — в разном понимании действия. Проверяй последовательность, а не ищи виновного.',drill:'Перед совместным заходом назови цель, момент и попроси короткое подтверждение.'},
  {name:'Контест за локу',tag:'НАЧАЛО МАТЧА',question:'Стоит ли менять всю точку высадки после одного проигранного контеста?',answer:'Один исход не показывает устойчивую проблему. Сравни хотя бы несколько сопоставимых попыток: высадку, доступный первый лут, позицию соперника и момент контакта. Если условия разные, не смешивай их в один вывод.',drill:'В двух контестах проверь один и тот же маршрут и отметь, что было доступно до первого контакта.'},
  {name:'Достаточно ли данных?',tag:'МЫШЛЕНИЕ ИГРОКА',question:'Упражнение не встретилось ни разу за сессию. Значит ли это, что оно бесполезно?',answer:'Нет. Ноль подходящих ситуаций — это отсутствие проверки, а не провал упражнения. Сохрани условие и повтори попытку позже. Оценивай выполнение действия только там, где оно действительно было возможно.',drill:'После сессии запиши число подходящих эпизодов отдельно от числа успешных действий.'},
  {name:'Информация в моменте',tag:'РАЗБОР',question:'На реплее противник виден заранее. Почему ты не заметил его в игре?',answer:'Реплей показывает больше, чем игрок воспринимал в моменте. Не называй решение ошибкой только потому, что теперь знаешь позицию соперника. Сначала выясни, какой сигнал был доступен тогда и мог ли ты реально на него отреагировать.',drill:'В одном повторе останови запись до контакта и выпиши только сигналы, доступные в моменте.'},
  {name:'Размен в команде',tag:'DUO И TRIO',question:'Тиммейт упал первым. Что проверить до вывода «он просто проиграл файт»?',answer:'Сравни дистанцию между игроками, угол поддержки и время между первым уроном и ответом команды. Если размен был недоступен изначально, причина может лежать в подготовке позиции или колле, а не в точности стрельбы.',drill:'Перед двумя командными файтами назови, кто может разменять первый контакт и из какого угла.'},
  {name:'Ресурсы и запасной план',tag:'ПОЗДНЯЯ ИГРА',question:'Ты дошёл до late game без ресурсов. В какой момент стоит искать причину?',answer:'Не ограничивайся последним файтом. Проследи, на каких решениях тратились ресурсы, когда был доступен безопасный сбор или другой путь и какие риски были известны заранее. Цель — найти первый управляемый выбор, а не объяснить всё одним числом.',drill:'После матча отметь два момента изменения запаса ресурсов и причину каждого.'},
  {name:'Проверка улучшения',tag:'ПРАКТИКА',question:'Сегодня ты выиграл больше файтов. Значит ли это, что упражнение сработало?',answer:'Не обязательно: соперники и условия могли быть другими. Сначала проверь, выполнил ли выбранное действие в подходящих ситуациях. Результат матча добавь отдельно. Сравнивать полезно похожие ситуации, а не только количество побед.',drill:'Считай три числа: подходящие ситуации, выполненные действия и результат этих эпизодов.'},
  {name:'Пауза после ошибки',tag:'ТУРНИРНЫЙ РИТМ',question:'После неудачной игры хочется сразу менять стратегию. Когда это разумно?',answer:'Сначала отдели единичный исход от повторяющегося паттерна. Короткая пауза помогает записать один факт, одну гипотезу и действие на следующую игру. Если данных мало, сохрани текущий план и собери ещё наблюдения.',drill:'После сложного матча запиши одну строку: факт → гипотеза → проверка в следующей игре.'},
  {name:'План выхода из файта',tag:'РИСК',question:'Ты начал файт с преимуществом. Когда стоит заранее решить, что пора отходить?',answer:'До входа назови условие отказа: потеря укрытия, дистанция до команды, HP или новый соперник. Условие зависит от ситуации, но если оно известно заранее, проще не продолжать бой только потому, что уже потратил ресурсы.',drill:'В двух файтах до первого размена назови конкретный сигнал для отхода.'}
];

export function renderTheory() {
  return `<div class="theory-page"><header class="theory-head"><span class="eyebrow">ЛАБОРАТОРИЯ ИГРЫ</span><h1>Учись замечать решение раньше ошибки.</h1><p>Короткие игровые ситуации, проверяемые принципы и упражнения. Сначала подумай сам, затем открой разбор.</p></header><div class="theory-grid">${topics.map((topic,index)=>`<article class="theory-card"><span class="theory-number">${String(index+1).padStart(2,'0')} · ${topic.tag}</span><h2>${topic.name}</h2><p class="theory-question">${topic.question}</p><details><summary>Открыть разбор</summary><p>${topic.answer}</p><div class="theory-drill"><strong>Проверь в игре</strong><p>${topic.drill}</p></div></details></article>`).join('')}</div><div class="theory-note"><strong>Правила игры меняются.</strong> Здесь собраны принципы принятия решений, а не обещания об актуальных предметах или сезонной мете. <a href="#plan">Перейти к сегодняшней практике →</a></div></div>`;
}
